/**
 * Returns true when the PR body contains an "Execution evidence" block with
 * non-empty content following the marker.
 *
 * Accepted marker forms (case-insensitive; mt#2648, widened mt#3968):
 *   - A Markdown heading, any level 1-6, with an OPTIONAL trailing colon
 *     (e.g. `## Execution evidence`, `### Execution evidence:`).
 *   - A standalone label line WITH a colon (`Execution evidence: <content>`) —
 *     the colon is REQUIRED for the non-heading form so bare prose containing
 *     the phrase doesn't false-positive.
 *   - The label form may be wrapped in `**bold**` / `__bold__` — either around
 *     the whole `Execution evidence:` including the colon, or around just the
 *     phrase with the colon outside (`**Execution evidence**:`) — and may be
 *     preceded by a leading `-`/`*`/`+` bullet marker. This mirrors the
 *     negative-control matcher's documented allowance (mt#3778) on the sibling
 *     hook, which already accepted this exact shape while this one did not.
 *     The colon is still REQUIRED either way — only the decoration around the
 *     label widened, not the delimiter that keeps bare prose out.
 *   - Negation phrases like "No Execution evidence:" do NOT qualify.
 *   - The marker must be followed by non-whitespace content (inline or on a
 *     subsequent line before the next heading).
 *
 * Detection strategy:
 *   1. Find a line that matches one of the accepted marker forms above.
 *   2. Verify the heading line itself does NOT start with "No " (negation guard).
 *   3. Require that there is at least one non-empty line of content after the
 *      heading and before the next Markdown heading or end-of-string.
 */
export function hasExecutionEvidence(prBody: string): boolean {
  return extractExecutionEvidenceRecords(prBody).length > 0;
}

/**
 * One `Execution evidence:` record: the marker line, plus the text belonging to it.
 *
 * The BODY is what a per-CLAIM provenance check needs (mt#4236). `Execution
 * evidence:` names a BLOCK, not a claim — one block routinely asserts a test run,
 * a typecheck, a lint pass and a format check at once — so a boolean cannot say
 * WHICH check a reader is being asked to believe, and the join that consumed the
 * boolean discharged all four of them on any test run in the session.
 *
 * {@link hasExecutionEvidence} is now a wrapper over this, so the two cannot
 * drift: the accepted forms, the fence rule, the negation guard and the
 * content requirement are stated ONCE. Same move mt#4044 made on the
 * negative-control matcher, for the same reason — a second matcher is how a
 * widening on one surface silently fails to reach the other, which is the
 * mt#4070 hazard by name.
 */
export interface ExecutionEvidenceRecord {
  /** The marker line, verbatim, as the matcher saw it. */
  label: string;
  /** Inline content on the marker line plus the lines beneath, up to the next real heading. */
  body: string;
}

/**
 * Every execution-evidence record in `prBody`, in document order.
 *
 * Carries the behavior {@link hasExecutionEvidence} used to implement inline;
 * that function's docblock above remains the statement of the accepted forms.
 */
export function extractExecutionEvidenceRecords(prBody: string): ExecutionEvidenceRecord[] {
  // Strip HTML comments before scanning. A marker inside <!-- ... --> is invisible
  // in rendered Markdown and must not count as evidence.
  const strippedBody = prBody.replace(/<!--[\s\S]*?-->/g, "");

  // Matches lines in one of two forms (mt#2648, widened mt#3968):
  //   A. Markdown heading (any level 1-6) + "execution evidence" with an
  //      OPTIONAL trailing colon — e.g. "## Execution evidence",
  //      "### Execution evidence:".
  //   B. Plain label line — "execution evidence:" with a REQUIRED colon (no
  //      heading marker). Keeping the colon required here preserves the
  //      original true-negative behavior for bare prose mentions. The label
  //      may carry an optional leading `-`/`*`/`+` bullet and optional
  //      `**`/`__` emphasis wrapping either the whole "phrase:" span (mt#3968
  //      AT1: `**Execution evidence:**`) or just the phrase with the colon
  //      outside (mt#3968 AT2 shape: `**Execution evidence**:`).
  // Anchored at start-of-line via the `m` flag — the bullet/emphasis
  // decoration is adjacency-anchored immediately before "execution evidence",
  // so a negation like "**No execution evidence:**" still cannot match: "No "
  // sits where the pattern requires the literal phrase, same as the plain
  // "No execution evidence:" case already did. Group 1 (heading hashes, form
  // A only) is unused downstream; the final group captures trailing inline
  // content. Up to 3 leading spaces before a heading marker, per CommonMark
  // (spaces only — not \s, which would let the match skip across blank lines).
  const BULLET_PREFIX = "(?: {0,3}[-*+]\\s+)?";
  const EMPHASIS = "(?:\\*\\*|__)?";
  const headingPattern = new RegExp(
    `^(?: {0,3}(#{1,6})\\s+execution evidence\\s*:?|${BULLET_PREFIX}${EMPHASIS}execution evidence${EMPHASIS}\\s*:${EMPHASIS})\\s*(.*)$`,
    "im"
  );

  const lines = strippedBody.split("\n");
  // Fence-aware (mt#3530). A marker whose only occurrence is inside a code fence is
  // QUOTED TEXT — a PR showing reviewers the expected shape — not a record. Before
  // this, such a body SATISFIED this blocking gate: `hasExecutionEvidence` imported
  // `computeFenceInternalLines` for its heading-collection helper below but never
  // applied it here, so a quoted example counted as real evidence.
  //
  // This aligns the gate with the two scanners that already do it
  // (`test-first-evidence.ts`, `success-criteria-coverage.ts`) and with the accepted-
  // forms class its siblings' doc comments claim to mirror.
  //
  // Blast radius measured before flipping, per the mt#3530 spec: replayed over the 100
  // most recently merged PRs — 0 verdict changes. The fenced CONTENT beneath a real
  // marker still counts, so the normal shape (label outside, output fenced under it) is
  // unaffected; only a marker with NO unfenced occurrence changes verdict.
  const fenceInternal = computeFenceInternalLines(lines);
  const records: ExecutionEvidenceRecord[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === undefined || fenceInternal[i]) continue;
    const match = line.match(headingPattern);
    if (!match) continue;

    // Negation guard: skip lines like "No Execution evidence:" or
    // "## No Execution evidence:" where the word before the marker is "No".
    // We check the full line up to "execution" for "no ".
    const beforeMarker = line.slice(0, line.toLowerCase().indexOf("execution")).toLowerCase();
    if (/\bno\b/.test(beforeMarker)) continue;

    // Also reject template placeholders where the heading line itself contains
    // the full text on the same line — allow only if there's content on the same
    // line OR content follows on subsequent lines.
    const inlineContent = (match[2] ?? "").trim();

    // The lines belonging to this marker: everything up to the next REAL heading.
    //
    // Only a REAL heading ends the section (PR #2533 R1). An evidence block IS a
    // pasted shell transcript, so a `# revert the fix first` comment inside the
    // fence looks like a heading and would truncate the scan — a false NEGATIVE,
    // and one that contradicts this function's own claim that fenced content
    // beneath a real marker still counts. Matches `collectHeadingSections` below
    // and `test-first-evidence.ts`, which both already gate on the fence.
    const following: string[] = [];
    for (let j = i + 1; j < lines.length; j++) {
      const nextLine = lines[j];
      if (nextLine === undefined) break;
      if (!fenceInternal[j] && /^ {0,3}#{1,6}\s/.test(nextLine)) break;
      following.push(nextLine);
    }

    // Inline content on the marker line counts as evidence on its own; otherwise
    // the section must carry at least one non-empty line. A marker with neither
    // yields NO record — keep looking, in case there is another block further
    // down. (This is the pre-mt#4236 `return true` / `keep looking` split,
    // restated as a push.)
    if (inlineContent.length > 0 || following.some((l) => l.trim().length > 0)) {
      records.push({
        label: line,
        body: [inlineContent, ...following].filter((l) => l !== "").join("\n"),
      });
    }
  }

  return records;
}

/**
 * Returns true when the PR title contains the bypass marker `[unverified-tests]`
 * anywhere in the title (case-insensitive).
 *
 * The marker is bracket-delimited, so it must appear as `[unverified-tests]` and
 * not merely as a substring embedded inside another word. Bracket delimiters provide
 * natural word-boundary semantics without requiring regex word boundaries (which do
 * not apply to `[`/`]` characters).
 *
 * Rationale: the sibling skill mt#1460 tells agents to put `[unverified-tests]` at
 * the start of their *input* title, but the `prepare-pr` tool then composes the
 * visible PR title as `feat(mt#X): <input title>`, placing the marker in the middle
 * (e.g. `feat(mt#1459): [unverified-tests] real title`). A startsWith check would
 * silently miss this common case.
 */
export function hasBypassPrefix(prTitle: string): boolean {
  return /\[unverified-tests\]/i.test(prTitle);
}

